@import url("https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@400;500;600&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
  Firefly: a warm, light system for consumer apps, with one glowing action.
  White page, warm paper surfaces, near-black ink and pill-shaped controls.
  The one lit thing on a screen is the primary action: a yellow-green pill
  with an inner top highlight and a soft bloom, brighter under the pointer.
  Every filled control (checkbox, switch, radio, slider) wears that same light.
*/

:root {
  /* ─── Ground: white page, warm paper surfaces, near-black ink ─── */
  --background: oklch(1 0 0);
  --foreground: oklch(0.168 0.004 106.8);

  --card: oklch(0.97 0.004 91.4);                       /* warm surface */
  --card-foreground: oklch(0.168 0.004 106.8);

  --popover: oklch(1 0 0);                    /* raised white panel */
  --popover-foreground: oklch(0.168 0.004 106.8);

  /* ─── Primary: the one glowing yellow-green action ─── */
  --primary: oklch(0.92 0.201 114);
  --primary-foreground: oklch(0.168 0.004 106.8);
  --primary-hover: oklch(0.879 0.194 114.2);
  --primary-active: oklch(0.825 0.184 114.6);
  --primary-text: oklch(0.52 0.12 115);          /* the accent as text on white: 5.4:1 */

  --secondary: oklch(0.949 0.005 95.1);
  --secondary-foreground: oklch(0.168 0.004 106.8);

  --muted: oklch(0.94 0.006 91.4);                       /* one step below the card, so a track or well on a card stays visible */
  --muted-foreground: oklch(0.523 0.011 100.1);

  --accent: oklch(0.949 0.005 95.1);                     /* hover and highlighted rows */
  --accent-foreground: oklch(0.168 0.004 106.8);

  --destructive: oklch(0.585 0.2 25.9);
  --destructive-foreground: oklch(1 0 0);

  --success: oklch(0.57 0.141 151.3);
  --success-foreground: oklch(1 0 0);
  --warning: oklch(0.641 0.14 69.1);
  --warning-foreground: oklch(0.168 0.004 106.8);

  --border: oklch(0.919 0.007 88.6);
  --input: oklch(0.919 0.007 88.6);             /* hairline grey: a field edge, or a quiet well where a part fills with it */
  --line-strong: oklch(0.848 0.01 93.6);        /* the strong line around fields and outline controls */
  --ring: oklch(0.594 0.135 115.4);                        /* olive ring: the accent at a contrast that reads */
  --radius: 0.75rem;
  /* Radius grows with the surface: chips, rows, fields, panels, sheets. */
  --radius-sm: 0.375rem;
  --radius-md: 0.625rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;

  /* ─── Warm surface ladder and ink ─── */
  --surface-2: oklch(0.949 0.005 95.1);
  --surface-3: oklch(0.919 0.007 88.6);
  --field: oklch(0.97 0.004 91.4);
  --foreground-secondary: oklch(0.404 0.01 99.1);
  --foreground-disabled: oklch(0.718 0.013 96.5);
  --control: oklch(0.607 0.012 89.8);                     /* unchecked box edges, scrub handles */
  --ink: oklch(0.168 0.004 106.8);
  --ink-hover: oklch(0.284 0.007 106.8);
  --ink-foreground: oklch(1 0 0);
  --thumb: oklch(1 0 0);
  --scrim: oklch(0.168 0.004 106.8 / 0.5);      /* dims the page behind dialogs and sheets */

  /* ─── Accent wash and tints ─── */
  --accent-wash: oklch(0.966 0.068 111.2);                 /* pressed chips, selected toggles */
  --accent-line: oklch(0.594 0.135 115.4);
  --success-tint: oklch(0.955 0.022 155.9);
  --success-text: oklch(0.481 0.118 151.5);
  --warning-tint: oklch(0.966 0.04 88.2);
  --warning-text: oklch(0.492 0.11 66);
  --destructive-tint: oklch(0.954 0.02 17.5);
  --destructive-text: oklch(0.501 0.181 26.8);

  --font-sans: "Hanken Grotesk", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* ─── Depth: warm hairline throws, never a hard edge ─── */
  --shadow-xs: 0 0.0625rem 0.0625rem oklch(0.26 0.028 95.8 / 0.04);
  --shadow-sm: 0 0.0625rem 0.125rem oklch(0.26 0.028 95.8 / 0.06), 0 0.0625rem 0.0625rem oklch(0.26 0.028 95.8 / 0.04);
  --shadow-md: 0 0.5rem 1.5rem -0.375rem oklch(0.26 0.028 95.8 / 0.16), 0 0.125rem 0.375rem oklch(0.26 0.028 95.8 / 0.06);
  /* A short lift for parts that float inside a card, such as a dragged row or
     a card stack. The deep throw belongs to dialogs and sheets alone, because
     a container that clips its content would cut it off in a hard line. */
  --shadow-lg: 0 0.625rem 1rem -0.25rem oklch(0.26 0.028 95.8 / 0.14), 0 0.25rem 0.375rem -0.25rem oklch(0.26 0.028 95.8 / 0.1);
  --shadow-card: var(--shadow-sm);
  --shadow-menu: var(--shadow-md);
  --shadow-overlay: 0 1.5rem 3rem -0.75rem oklch(0.26 0.028 95.8 / 0.24), 0 0.25rem 0.75rem oklch(0.26 0.028 95.8 / 0.08);
  --shadow-thumb: 0 0.125rem 0.3125rem oklch(0.26 0.028 95.8 / 0.1), 0 0.0625rem 0.0625rem oklch(0.26 0.028 95.8 / 0.07), 0 0 0 0.03125rem oklch(0.26 0.028 95.8 / 0.1);

  /* ─── Signature: the lit pill. Highlights sit over a two-stop gradient,
     and a brighter layer fades in on hover. ─── */
  --gradient-primary:
    linear-gradient(180deg, oklch(1 0 0 / 0.3) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.24) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.32) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.9 0.199 115) 0%, oklch(0.968 0.155 112.5) 100%);
  --gradient-primary-hover:
    linear-gradient(180deg, oklch(1 0 0 / 0.38) 0%, oklch(1 0 0 / 0) 48%),
    radial-gradient(110% 95% at 22% 0%, oklch(1 0 0 / 0.3) 0%, oklch(1 0 0 / 0) 62%),
    radial-gradient(75% 65% at 50% 115%, oklch(1 0 0 / 0.42) 0%, oklch(1 0 0 / 0) 72%),
    linear-gradient(180deg, oklch(0.924 0.2 114.6) 9%, oklch(0.975 0.122 110.9) 100%);
  --gradient-primary-active:
    linear-gradient(180deg, oklch(1 0 0 / 0.3) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.24) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.32) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.844 0.189 115.4) 0%, oklch(0.923 0.183 113.5) 100%);
  --shadow-primary:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.75),
    inset 0 -0.09375rem 0.125rem 0 oklch(1 0 0 / 0.7),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.2),
    inset 0 0 0.75rem 0 oklch(1 0 0 / 0.28),
    0 0 0 0.0625rem oklch(0.548 0.116 114.4 / 0.22);
  --shadow-primary-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.9),
    inset 0 -0.03125rem 0.0625rem 0 oklch(1 0 0 / 0.9),
    inset 0 -0.0625rem 0.1875rem 0 oklch(1 0 0 / 0.9),
    inset 0 -0.09375rem 0.3125rem 0 oklch(1 0 0 / 0.9),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.28),
    inset 0 0 0.875rem 0 oklch(1 0 0 / 0.4);
  /* Small filled controls wear the same lit material at a tighter radius. */
  --shadow-control:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.7),
    inset 0 -0.0625rem 0.09375rem 0 oklch(1 0 0 / 0.7),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.18),
    inset 0 0 0.375rem 0 oklch(1 0 0 / 0.28),
    0 0 0 0.0625rem oklch(0.548 0.116 114.4 / 0.2);
  --shadow-control-hover:
    inset 0 -0.03125rem 0.0625rem 0 oklch(1 0 0 / 0.9),
    inset 0 -0.0625rem 0.15625rem 0 oklch(1 0 0 / 0.9),
    inset 0 0 0.5rem 0 oklch(1 0 0 / 0.4);

  --gradient-destructive:
    linear-gradient(180deg, oklch(1 0 0 / 0.12) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.096) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.128) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.466 0.168 26.7) 0%, oklch(0.538 0.189 26.4) 100%);
  --gradient-destructive-hover:
    linear-gradient(180deg, oklch(1 0 0 / 0.152) 0%, oklch(1 0 0 / 0) 48%),
    radial-gradient(110% 95% at 22% 0%, oklch(1 0 0 / 0.12) 0%, oklch(1 0 0 / 0) 62%),
    radial-gradient(75% 65% at 50% 115%, oklch(1 0 0 / 0.168) 0%, oklch(1 0 0 / 0) 72%),
    linear-gradient(180deg, oklch(0.495 0.176 26.6) 9%, oklch(0.566 0.194 26) 100%);
  --gradient-destructive-active:
    linear-gradient(180deg, oklch(1 0 0 / 0.12) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.096) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.128) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.412 0.149 26.8) 0%, oklch(0.477 0.171 26.7) 100%);
  --shadow-destructive:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.3),
    inset 0 -0.09375rem 0.125rem 0 oklch(1 0 0 / 0.4),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.08),
    inset 0 0 0.75rem 0 oklch(1 0 0 / 0.16),
    0 0 0 0.0625rem oklch(0.403 0.135 25.7 / 0.22);
  --shadow-destructive-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.36),
    inset 0 -0.03125rem 0.0625rem 0 oklch(1 0 0 / 0.6),
    inset 0 -0.0625rem 0.1875rem 0 oklch(1 0 0 / 0.6),
    inset 0 -0.09375rem 0.3125rem 0 oklch(1 0 0 / 0.6),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.112),
    inset 0 0 0.875rem 0 oklch(1 0 0 / 0.24);

  /* ─── Charts: lit accent first, then warm companions ─── */
  --chart-1: oklch(0.825 0.184 114.6);
  --chart-2: oklch(0.168 0.004 106.8);
  --chart-3: oklch(0.594 0.135 115.4);
  --chart-4: oklch(0.641 0.14 69.1);
  --chart-5: oklch(0.607 0.012 89.8);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

.dark {
  --background: oklch(0.163 0.004 106.8);
  --foreground: oklch(0.964 0.007 97.4);
  --card: oklch(0.217 0.006 106.9);
  --card-foreground: oklch(0.964 0.007 97.4);
  --popover: oklch(0.238 0.006 106.8);
  --popover-foreground: oklch(0.964 0.007 97.4);
  --primary: oklch(0.841 0.161 114);
  --primary-foreground: oklch(0.168 0.004 106.8);
  --primary-hover: oklch(0.879 0.152 114);
  --primary-active: oklch(0.79 0.161 113.9);
  --primary-text: oklch(0.841 0.161 114);
  --secondary: oklch(0.267 0.007 106.9);
  --secondary-foreground: oklch(0.964 0.007 97.4);
  --muted: oklch(0.29 0.008 106.9);
  --muted-foreground: oklch(0.679 0.012 95.2);
  --accent: oklch(0.267 0.007 106.9);
  --accent-foreground: oklch(0.964 0.007 97.4);
  --destructive: oklch(0.626 0.193 23);
  --destructive-foreground: oklch(0.168 0.004 106.8);
  --success: oklch(0.8 0.182 151.7);
  --success-foreground: oklch(0.168 0.004 106.8);
  --warning: oklch(0.817 0.164 75.8);
  --warning-foreground: oklch(0.168 0.004 106.8);
  --border: oklch(0.299 0.009 106.9);
  --input: oklch(0.299 0.009 106.9);
  --line-strong: oklch(0.366 0.01 106.9);
  --ring: oklch(0.841 0.161 114);
  --surface-2: oklch(0.267 0.007 106.9);
  --surface-3: oklch(0.315 0.009 106.9);
  --field: oklch(0.217 0.006 106.9);
  --foreground-secondary: oklch(0.829 0.013 96.5);
  --foreground-disabled: oklch(0.477 0.01 99);
  --control: oklch(0.626 0.012 95.3);
  --ink: oklch(0.964 0.007 97.4);
  --ink-hover: oklch(0.903 0.011 95.2);
  --ink-foreground: oklch(0.168 0.004 106.8);
  --thumb: oklch(1 0 0);
  --scrim: oklch(0 0 0 / 0.64);
  --accent-wash: oklch(0.29 0.052 113.9);
  --accent-line: oklch(0.841 0.161 114);
  --success-tint: oklch(0.254 0.039 154.6);
  --success-text: oklch(0.839 0.154 153.8);
  --warning-tint: oklch(0.26 0.043 83.1);
  --warning-text: oklch(0.862 0.139 81.9);
  --destructive-tint: oklch(0.228 0.041 18.3);
  --destructive-text: oklch(0.761 0.142 20.9);
  --shadow-xs: 0 0.0625rem 0.0625rem oklch(0 0 0 / 0.3);
  --shadow-sm: 0 0.0625rem 0.125rem oklch(0 0 0 / 0.4);
  --shadow-md: 0 0.5rem 1.5rem -0.375rem oklch(0 0 0 / 0.6), 0 0 0 0.0625rem oklch(0.299 0.009 106.9);
  --shadow-lg: 0 0.625rem 1rem -0.25rem oklch(0 0 0 / 0.5), 0 0 0 0.0625rem oklch(0.299 0.009 106.9);
  --shadow-card: var(--shadow-sm);
  --shadow-menu: var(--shadow-md);
  --shadow-overlay: 0 1.5rem 3rem -0.75rem oklch(0 0 0 / 0.7), 0 0 0 0.0625rem oklch(0.299 0.009 106.9);
  --shadow-thumb: 0 0.125rem 0.3125rem oklch(0 0 0 / 0.22), 0 0.0625rem 0.0625rem oklch(0 0 0 / 0.16), 0 0 0 0.03125rem oklch(0 0 0 / 0.2);
  --gradient-primary:
    linear-gradient(180deg, oklch(1 0 0 / 0.075) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.06) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.08) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.814 0.16 113.8) 0%, oklch(0.879 0.136 117) 100%);
  --gradient-primary-hover:
    linear-gradient(180deg, oklch(1 0 0 / 0.095) 0%, oklch(1 0 0 / 0) 48%),
    radial-gradient(110% 95% at 22% 0%, oklch(1 0 0 / 0.075) 0%, oklch(1 0 0 / 0) 62%),
    radial-gradient(75% 65% at 50% 115%, oklch(1 0 0 / 0.105) 0%, oklch(1 0 0 / 0) 72%),
    linear-gradient(180deg, oklch(0.835 0.161 114.1) 9%, oklch(0.899 0.128 116.8) 100%);
  --gradient-primary-active:
    linear-gradient(180deg, oklch(1 0 0 / 0.075) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.06) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.08) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.78 0.161 113.9) 0%, oklch(0.84 0.145 116) 100%);
  --shadow-primary:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.188),
    inset 0 -0.09375rem 0.125rem 0 oklch(1 0 0 / 0.3),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.05),
    inset 0 0 0.75rem 0 oklch(1 0 0 / 0.12),
    0 0 0 0.0625rem oklch(0 0 0 / 0.22);
  --shadow-primary-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.225),
    inset 0 -0.03125rem 0.0625rem 0 oklch(1 0 0 / 0.45),
    inset 0 -0.0625rem 0.1875rem 0 oklch(1 0 0 / 0.45),
    inset 0 -0.09375rem 0.3125rem 0 oklch(1 0 0 / 0.45),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.07),
    inset 0 0 0.875rem 0 oklch(1 0 0 / 0.18);
  /* Small filled controls wear the same lit material at a tighter radius. */
  --shadow-control:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.175),
    inset 0 -0.0625rem 0.09375rem 0 oklch(1 0 0 / 0.3),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.045),
    inset 0 0 0.375rem 0 oklch(1 0 0 / 0.12),
    0 0 0 0.0625rem oklch(0 0 0 / 0.2);
  --shadow-control-hover:
    inset 0 -0.03125rem 0.0625rem 0 oklch(1 0 0 / 0.45),
    inset 0 -0.0625rem 0.15625rem 0 oklch(1 0 0 / 0.45),
    inset 0 0 0.5rem 0 oklch(1 0 0 / 0.18);

  --gradient-destructive:
    linear-gradient(180deg, oklch(1 0 0 / 0.3) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.24) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.32) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.606 0.183 22.6) 0%, oklch(0.694 0.169 20.4) 100%);
  --gradient-destructive-hover:
    linear-gradient(180deg, oklch(1 0 0 / 0.38) 0%, oklch(1 0 0 / 0) 48%),
    radial-gradient(110% 95% at 22% 0%, oklch(1 0 0 / 0.3) 0%, oklch(1 0 0 / 0) 62%),
    radial-gradient(75% 65% at 50% 115%, oklch(1 0 0 / 0.42) 0%, oklch(1 0 0 / 0) 72%),
    linear-gradient(180deg, oklch(0.648 0.172 21.1) 9%, oklch(0.741 0.145 19.7) 100%);
  --gradient-destructive-active:
    linear-gradient(180deg, oklch(1 0 0 / 0.3) 0%, oklch(1 0 0 / 0) 45%),
    radial-gradient(110% 90% at 22% 0%, oklch(1 0 0 / 0.24) 0%, oklch(1 0 0 / 0) 60%),
    radial-gradient(70% 60% at 50% 115%, oklch(1 0 0 / 0.32) 0%, oklch(1 0 0 / 0) 70%),
    linear-gradient(0deg, oklch(0 0 0 / 0.05) 0%, oklch(0 0 0 / 0) 18%),
    linear-gradient(180deg, oklch(0.59 0.178 22.6) 0%, oklch(0.673 0.17 20.7) 100%);
  --shadow-destructive:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.75),
    inset 0 -0.09375rem 0.125rem 0 oklch(1 0 0 / 0.5),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.2),
    inset 0 0 0.75rem 0 oklch(1 0 0 / 0.2),
    0 0 0 0.0625rem oklch(0 0 0 / 0.22);
  --shadow-destructive-hover:
    inset 0 0.0625rem 0 0 oklch(1 0 0 / 0.9),
    inset 0 -0.03125rem 0.0625rem 0 oklch(1 0 0 / 0.75),
    inset 0 -0.0625rem 0.1875rem 0 oklch(1 0 0 / 0.75),
    inset 0 -0.09375rem 0.3125rem 0 oklch(1 0 0 / 0.75),
    inset 0 0 0 0.0625rem oklch(1 0 0 / 0.28),
    inset 0 0 0.875rem 0 oklch(1 0 0 / 0.3);

  --chart-1: oklch(0.841 0.161 114);
  --chart-2: oklch(0.964 0.007 97.4);
  --chart-3: oklch(0.679 0.012 95.2);
  --chart-4: oklch(0.817 0.164 75.8);
  --chart-5: oklch(0.477 0.01 99);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
